/* ---------- Command palette ---------- */
.cpl{overflow:hidden;display:flex;flex-direction:column;box-shadow:var(--shadow-pop)}
.cpl-in{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line);color:var(--muted)}
.cpl-q{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:14px;color:var(--fg)}
.cpl-q::placeholder{color:var(--muted)}
.cpl-list{padding:6px;height:236px;overflow-y:auto;position:relative}
.cpl-g{font-size:11.5px;color:var(--muted);padding:8px 8px 4px}
.cpl-i{display:flex;align-items:center;gap:10px;width:100%;height:36px;padding:0 8px;border-radius:10px;font-size:13.5px;text-align:left;color:var(--fg);position:relative;z-index:1}
.cpl-i .ic{width:24px;height:24px;border-radius:7px;display:grid;place-items:center;background:var(--chip);color:var(--fg2);flex:none;transition:background .2s,color .2s}
.cpl-i.hl .ic{background:var(--surface);color:var(--accent-fg,var(--accent))}
.cpl-i .k{margin-left:auto;display:flex;gap:3px}
.cpl-i mark{background:transparent;color:var(--accent-fg,var(--accent));font-weight:500}
.cpl-i.ask .ic{background:var(--accent);color:var(--on-accent)}
.cpl-hl{position:absolute;left:6px;right:6px;height:36px;border-radius:10px;background:var(--chip);transition:top .25s var(--ease);z-index:0}
.cpl-f{display:flex;gap:14px;align-items:center;padding:8px 14px;border-top:1px solid var(--line);font-size:11.5px}
.cpl-f .kbd{margin-right:3px}
.cpl-st{margin-left:auto;color:var(--fg2)}
.cpl-empty{padding:30px 10px;text-align:center;font-size:13px;color:var(--muted)}

DM.def('command-palette', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{search}', I('search'));
  const C = [
    ['Agent','spark','Audit this page for contrast',['⌘','J']],
    ['Agent','wand','Tidy layer names in the selection'],
    ['Agent','code','Export tokens as CSS variables'],
    ['Go to','layers','Pricing v4',['G','P']],
    ['Go to','figma','Checkout flow'],
    ['Go to','book','Memory'],
    ['Actions','users','Invite a teammate'],
    ['Actions','gear','Agent settings',['⌘',',']],
    ['Actions','palette','Switch theme']
  ];
  const q = $('.cpl-q', r), list = $('.cpl-list', r), st = $('.cpl-st', r);
  let items = [], hi = 0;
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  function paint(){
    const v = q.value.trim(), re = v ? new RegExp('(' + v.split('').map(esc).join(').*?(') + ')', 'i') : null;
    const m = C.filter(x => !re || re.test(x[2]));
    let h = '<span class="cpl-hl"></span>', g = '';
    m.forEach(x => { if (x[0] !== g){ g = x[0]; h += `<div class="cpl-g">${g}</div>`; } const label = v ? x[2].replace(new RegExp(v.split('').map(esc).join('|'), 'gi'), s => `<mark>${s}</mark>`) : x[2];
      h += `<button class="cpl-i" role="option" data-t="${x[2]}">${'<span class="ic">' + I(x[1],'xs') + '</span>'}<span>${label}</span>${x[3] ? `<span class="k">${x[3].map(k => `<span class="kbd">${k}</span>`).join('')}</span>` : ''}</button>`; });
    if (v) h += `<div class="cpl-g">Ask</div><button class="cpl-i ask" data-t="${v.replace(/"/g,'&quot;')}" data-ask="1"><span class="ic">${I('up','xs')}</span><span>Ask the agent: “${v.replace(/</g,'&lt;')}”</span></button>`;
    list.innerHTML = h; items = $$('.cpl-i', list); hi = 0; move(0);
    items.forEach((b, i) => { b.onmouseenter = () => move(i - hi); b.onclick = () => run(b); });
  }
  function move(d){ if (!items.length) return; hi = (hi + d + items.length) % items.length; items.forEach((b, i) => b.classList.toggle('hl', i === hi)); const b = items[hi], hl = $('.cpl-hl', list); hl.style.top = b.offsetTop + 'px'; if (b.offsetTop < list.scrollTop || b.offsetTop + 36 > list.scrollTop + list.clientHeight) list.scrollTo({ top:b.offsetTop - 40, behavior:'smooth' }); }
  function run(b){ swap(st, b.dataset.ask ? 'Sent to the agent' : 'Ran: ' + b.dataset.t); b.animate([{ transform:'scale(1)' },{ transform:'scale(.98)' },{ transform:'scale(1)' }], { duration:260, easing:'ease-out' }); }
  q.oninput = paint;
  q.onkeydown = e => { if (e.key === 'ArrowDown'){ move(1); e.preventDefault(); } else if (e.key === 'ArrowUp'){ move(-1); e.preventDefault(); } else if (e.key === 'Enter' && items[hi]) run(items[hi]); else if (e.key === 'Escape'){ q.value = ''; paint(); } };
  paint();
  c.run(async () => { await c.wait(1500); for (const ch of 'tok'){ q.value += ch; paint(); await c.wait(180); } });
});
